import boto3
from botocore.config import Config

def get_s3_client():
    # AWS S3 client with a specific configuration
    s3_config = Config(
        region_name='us-east-1',
        signature_version='s3v4',
    )
    return boto3.client('s3', config=s3_config)

def get_textract_client():
    # AWS Textract client
    return boto3.client('textract', region_name='us-east-1')

def get_translate_client():
    # AWS Translate client
    return boto3.client('translate', region_name='us-east-1')

def get_comprehend_client():
    # AWS Comprehend client for summarization and entity extraction
    return boto3.client('comprehend', region_name='us-east-1')

def get_bedrock_runtime_client():
    # AWS Bedrock Runtime client for embedding models like Titan Embedding
    return boto3.client('bedrock-runtime', region_name='us-east-1')

import os
from typing import Union

from storage_client import get_s3_client
from storage_models import UploadObjectRequest, UploadObjectResponse

def upload_object(
    request: UploadObjectRequest,
) -> UploadObjectResponse:
    """Uploads a file or byte stream to AWS S3 managed object storage."""
    s3_client = get_s3_client()

    if request.file_path:
        if not os.path.exists(request.file_path):
            raise FileNotFoundError(f"File not found at {request.file_path}")
        extra_args = {}
        if request.content_type:
            extra_args['ContentType'] = request.content_type
        with open(request.file_path, 'rb') as f:
            response = s3_client.upload_fileobj(
                f,
                request.bucket_name,
                request.object_key,
                ExtraArgs=extra_args
            )
    elif request.data:
        extra_args = {}
        if request.content_type:
            extra_args['ContentType'] = request.content_type
        response = s3_client.put_object(
            Bucket=request.bucket_name,
            Key=request.object_key,
            Body=request.data,
            **extra_args
        )
    else:
        raise ValueError("Either file_path or data must be provided.")

    # The upload_fileobj and put_object methods don't return the same structure
    # For simplicity, we'll perform a head_object to get ETag and VersionId if needed
    # or assume success if no exception was raised.
    try:
        head_response = s3_client.head_object(
            Bucket=request.bucket_name,
            Key=request.object_key
        )
        e_tag = head_response.get('ETag', '').strip('\"')
        version_id = head_response.get('VersionId')
    except Exception: # Fallback if head_object fails or is not needed
        e_tag = "unknown"
        version_id = None

    return UploadObjectResponse(
        object_key=request.object_key,
        e_tag=e_tag,
        version_id=version_id,
        upload_success=True,
    )

from storage_client import get_s3_client
from storage_models import PresignedDownloadRequest, PresignedDownloadResponse

def create_presigned_download_url(
    request: PresignedDownloadRequest,
) -> PresignedDownloadResponse:
    """Creates a time-limited signed download URL for an AWS S3 stored object."""
    s3_client = get_s3_client()

    try:
        presigned_url = s3_client.generate_presigned_url(
            'get_object',
            Params={
                'Bucket': request.bucket_name,
                'Key': request.object_key
            },
            ExpiresIn=request.expiration_seconds,
        )
        return PresignedDownloadResponse(presigned_url=presigned_url)
    except Exception as e:
        raise RuntimeError(f"Error generating presigned URL: {e}") from e

from storage_client import get_s3_client
from storage_models import ObjectMetadataRequest, ObjectMetadataResponse

def get_object_metadata(
    request: ObjectMetadataRequest,
) -> ObjectMetadataResponse:
    """Reads object metadata or head information from AWS S3 managed object storage."""
    s3_client = get_s3_client()

    try:
        response = s3_client.head_object(
            Bucket=request.bucket_name,
            Key=request.object_key,
        )
        # Clean up response to remove non-serializable parts if necessary,
        # and focus on relevant metadata.
        metadata = {
            'ContentLength': response.get('ContentLength'),
            'ContentType': response.get('ContentType'),
            'ETag': response.get('ETag'),
            'LastModified': response.get('LastModified').isoformat() if response.get('LastModified') else None,
            'VersionId': response.get('VersionId'),
            'ServerSideEncryption': response.get('ServerSideEncryption'),
            'Metadata': response.get('Metadata', {}), # Custom metadata
        }
        return ObjectMetadataResponse(
            object_key=request.object_key,
            metadata={k: v for k, v in metadata.items() if v is not None}
        )
    except s3_client.exceptions.ClientError as e:
        if e.response['Error']['Code'] == '404':
            raise FileNotFoundError(f"Object {request.object_key} not found in bucket {request.bucket_name}") from e
        raise RuntimeError(f"Error retrieving object metadata: {e}") from e

from storage_client import get_s3_client
from storage_models import ListPrefixRequest, ListPrefixResponse

def list_objects_with_prefix(
    request: ListPrefixRequest,
) -> ListPrefixResponse:
    """Lists stored objects under an AWS S3 bucket prefix."""
    s3_client = get_s3_client()

    object_keys = []
    common_prefixes = []

    paginator = s3_client.get_paginator('list_objects_v2')
    pages = paginator.paginate(
        Bucket=request.bucket_name,
        Prefix=request.prefix,
        MaxKeys=request.max_keys,
        Delimiter='/'
    )

    for page in pages:
        if 'Contents' in page:
            for obj in page['Contents']:
                object_keys.append(obj['Key'])
        if 'CommonPrefixes' in page:
            for common_prefix in page['CommonPrefixes']:
                common_prefixes.append(common_prefix['Prefix'])

    return ListPrefixResponse(
        prefix=request.prefix,
        object_keys=object_keys,
        common_prefixes=common_prefixes,
    )

import json
import time

from storage_client import get_s3_client, get_textract_client
from storage_models import StoredDocumentOcrRequest, StoredDocumentOcrResponse

def run_ocr_on_stored_document(
    request: StoredDocumentOcrRequest,
) -> StoredDocumentOcrResponse:
    """Runs OCR on a stored document object using AWS Textract."""
    textract_client = get_textract_client()
    s3_client = get_s3_client()

    # Start asynchronous detection of text
    response = textract_client.start_document_text_detection(
        DocumentLocation={
            'S3Object': {
                'Bucket': request.bucket_name,
                'Name': request.object_key
            }
        }
    )
    job_id = response['JobId']

    print(f"Started Textract job with ID: {job_id}")

    # Poll for job completion (simplified, in a real scenario use SNS/SQS)
    status = 'IN_PROGRESS'
    while status == 'IN_PROGRESS':
        time.sleep(5)  # Wait for 5 seconds before polling again
        job_status_response = textract_client.get_document_text_detection(
            JobId=job_id
        )
        status = job_status_response['JobStatus']
        print(f"Textract job {job_id} status: {status}")

    if status == 'SUCCEEDED':
        extracted_text = []
        pages = []
        next_token = None

        while True:
            if next_token:
                result_response = textract_client.get_document_text_detection(
                    JobId=job_id,
                    NextToken=next_token
                )
            else:
                result_response = textract_client.get_document_text_detection(
                    JobId=job_id
                )

            blocks = result_response['Blocks']
            for block in blocks:
                if block['BlockType'] == 'LINE':
                    extracted_text.append(block['Text'])

            if 'NextToken' in result_response:
                next_token = result_response['NextToken']
            else:
                break

        return StoredDocumentOcrResponse(
            object_key=request.object_key,
            extracted_text="\n".join(extracted_text),
            job_id=job_id,
        )
    else:
        raise RuntimeError(f"Textract job {job_id} failed with status: {status}")
